/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {


        return when(buf.getInt()) {
            1 -> FfiException.BadArgs(
                FfiConverterString.read(buf),
                )
            2 -> FfiException.BadQr(
                FfiConverterString.read(buf),
                )
            3 -> FfiException.PinMismatch()
            4 -> FfiException.NotEnrolled()
            5 -> FfiException.UnknownContact()
            6 -> FfiException.NotAccepted()
            7 -> FfiException.Blocked()
            8 -> FfiException.IdentityMismatch()
            9 -> FfiException.NothingToConfirm()
            10 -> FfiException.MissingKeys()
            11 -> FfiException.NoPeerPrekeys()
            12 -> FfiException.UploadRejected()
            13 -> FfiException.Quota()
            14 -> FfiException.Revoked()
            15 -> FfiException.InvalidCredentials()
            16 -> FfiException.LoginTaken()
            17 -> FfiException.InviteRequired()
            18 -> FfiException.InviteExpired()
            19 -> FfiException.InviteRevoked()
            20 -> FfiException.InviteUsed()
            21 -> FfiException.AuthRateLimited()
            22 -> FfiException.InvalidInput()
